with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الممارسة المهنية وإدارة خدمات الأرصاد الجوية','هيكل خدمات الأرصاد والمناوبات والتحليل والإحاطات والتحذيرات والمنتجات القطاعية ومراجعة الأداء.',25,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'إدارة خدمات الأرصاد',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التحليل التشغيلي وإنتاج التوقع',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التحذير والتواصل التشغيلي',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u4 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'المنتجات القطاعية والتقارير',4,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u5 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الجودة والتطوير المهني',5,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('national-meteorological-service-structure','هيكل خدمات الأرصاد الجوية الوطنية ومعايير العمل','الأدوار المؤسسية وشبكات الرصد والتنبؤ والخدمات والإنذار.','{"blocks":[{"type":"text","text":"تقدم خدمات الأرصاد الجوية الوطنية معلومات عن الطقس والمناخ والظواهر الخطرة لدعم السلامة والاقتصاد والتخطيط."},{"type":"text","text":"تتكون الخدمة عادة من شبكات رصد ومراكز تحليل وتنبؤ واتصالات وأرشفة وخدمات مناخية وتعاون دولي."},{"type":"text","text":"تجمع شبكات الرصد القياسات السطحية والعلوية والبحرية والرادارية والفضائية وفق الإمكانات الوطنية."},{"type":"text","text":"تتولى مراكز التنبؤ تحليل الحالة الراهنة وإنتاج التوقعات ومتابعة تطور الظواهر وإصدار المنتجات التشغيلية."},{"type":"text","text":"تدعم أقسام المناخ مراقبة الاتجاهات والمعدلات والتطرفات وتوفير المعلومات طويلة الأمد."},{"type":"text","text":"تتطلب خدمات الإنذار المبكر تنسيقاً مع الجهات المسؤولة عن إدارة الطوارئ والقطاعات المتأثرة."},{"type":"text","text":"تسهم المعايير والتعاريف الدولية في جعل البيانات والمنتجات قابلة للتبادل والمقارنة بين الدول."},{"type":"text","text":"تحتاج الخدمة إلى نظام جودة موثق يحدد المسؤوليات وإجراءات التشغيل ومراجعة المنتجات."},{"type":"text","text":"تعد استمرارية التشغيل والنسخ الاحتياطي والاتصالات البديلة من متطلبات البنية المؤسسية."},{"type":"text","text":"يجب أن تتوافق المنتجات مع احتياجات المستخدمين مع الحفاظ على الدقة العلمية والشفافية."},{"type":"text","text":"مثال: تحذير فيضان فعال يتطلب تعاون الأرصاد والهيدرولوجيا والسلطات المحلية وقنوات الاتصال."},{"type":"callout","text":"خلاصة: الخدمة الوطنية منظومة مؤسسية مترابطة وليست مجرد محطة أو نموذج تنبؤ."}]}',1760,50,'["تحديد مكونات الخدمة الوطنية","شرح تكامل الرصد والتنبؤ","فهم دور المعايير الدولية"]','إدارة خدمات الأرصاد'),
('operational-forecast-shift-management','إدارة مناوبة التنبؤ الجوي وتسليم العمل','تنظيم المناوبات وسجلات الحالة ومتابعة البيانات وتوزيع المسؤوليات.','{"blocks":[{"type":"text","text":"تضمن المناوبة التشغيلية استمرارية مراقبة الطقس وتحليل البيانات وإصدار المنتجات على مدار الساعة عند الحاجة."},{"type":"text","text":"تبدأ المناوبة بمراجعة الحالة الجوية الحالية والتحذيرات السارية والتوقعات السابقة والبيانات المتأخرة."},{"type":"text","text":"يجب التحقق من حداثة مصادر الرصد والنماذج وحالة الاتصالات قبل الاعتماد على المنتجات."},{"type":"text","text":"تتضمن متابعة الحالة رصد تطور الأنظمة الجوية ومقارنة التوقعات بالمشاهدات وتحديد الانحرافات المهمة."},{"type":"text","text":"يسجل المتنبئ القرارات والتعديلات وأسبابها ووقت إصدارها ومصادر المعلومات المستخدمة."},{"type":"text","text":"يجب أن يوضح تسليم المناوبة الأنظمة المؤثرة والفترات الحساسة والبيانات الناقصة والمنتجات التي تحتاج تحديثاً."},{"type":"text","text":"توزع المسؤوليات بوضوح بين التحليل وإعداد التوقع ومراجعة التحذير والتواصل وفق هيكل المركز."},{"type":"text","text":"تستخدم قوائم تحقق لتقليل إغفال خطوات أساسية في فترات الضغط التشغيلي."},{"type":"text","text":"يجب توثيق أي عطل في مصدر البيانات أو اختلاف بين المنتجات وتأثيره المحتمل في القرار."},{"type":"text","text":"تساعد مراجعة المناوبات بعد الحالات الشديدة على تطوير الإجراءات والتدريب."},{"type":"text","text":"مثال: إذا أظهر الرادار تطوراً جديداً قبل موعد التحديث الدوري، توثق المناوبة التغير وتعيد تقييم المنتج وفق إجراءات المركز."},{"type":"callout","text":"خلاصة: إدارة المناوبة تجمع الانضباط والتوثيق والتواصل والتحليل المستمر."}]}',1770,50,'["شرح مهام المتنبئ المناوب","تنظيم تسليم المناوبة","إدارة سجلات الحالة"]','إدارة خدمات الأرصاد'),
('synoptic-analysis-practical-workflow','منهجية التحليل السينوبتيكي العملي خطوة بخطوة','دمج خرائط السطح والطبقات العليا والرصد في تشخيص حالة جوية.','{"blocks":[{"type":"text","text":"يبدأ التحليل السينوبتيكي بتحديد وقت الحالة والمنطقة ومصادر الرصد المتاحة."},{"type":"text","text":"تفحص خرائط الضغط السطحي لتحديد المنخفضات والمرتفعات والجبهات وتدرج الضغط."},{"type":"text","text":"تراجع خرائط 850 hPa لفهم الحرارة والرطوبة والرياح في الطبقات السفلى مع مراعاة التضاريس."},{"type":"text","text":"تستخدم خرائط 700 hPa لتقييم الرطوبة والحركة الرأسية في الطبقات المتوسطة."},{"type":"text","text":"تستخدم خرائط 500 hPa لتحديد الأخاديد والنتوءات والدوامية والبنية الموجية."},{"type":"text","text":"تستخدم خرائط 300 hPa لتحليل التيارات النفاثة والتباعد والقص في الطبقات العليا."},{"type":"text","text":"تقارن الخرائط المتزامنة لتحديد ميل الأنظمة وتطورها الرأسي ومناطق التفاعل."},{"type":"text","text":"تراجع صور الأقمار والرادار لتأكيد البنية السحابية والهطول المرصود وتطور الخلايا."},{"type":"text","text":"تفحص ملفات السبر لتقييم الاستقرار والرطوبة والقص والطبقات الانقلابية."},{"type":"text","text":"تحدد السيناريوهات المحتملة وتفصل بين ما تدعمه المشاهدات وما يعتمد على توقع النموذج."},{"type":"text","text":"مثال: تشخيص منخفض سطحي يحتاج ربطه بالأخدود العلوي والرطوبة والرفع والرصد الفعلي لا الاكتفاء بمركز الضغط."},{"type":"callout","text":"خلاصة: التحليل السينوبتيكي الجيد تركيب متعدد المصادر والمستويات والزمن."}]}',1780,50,'["بناء تشخيص سينوبتيكي متكامل","ربط السطح بالطبقات العليا","تحديد تطور النظام"]','التحليل التشغيلي وإنتاج التوقع'),
('forecast-briefing-and-weather-discussion','إعداد الإحاطة الجوية ومناقشة التوقعات','تحويل التحليل إلى عرض مهني واضح للأنظمة والفترات ومجالات عدم اليقين.','{"blocks":[{"type":"text","text":"تهدف الإحاطة الجوية إلى تقديم صورة مختصرة ومترابطة للحالة الراهنة والتطور المتوقع."},{"type":"text","text":"تبدأ الإحاطة بتحديد الفترة والمناطق والظواهر ذات الأهمية التشغيلية."},{"type":"text","text":"تعرض الحالة الراهنة من خلال الضغط والجبهات والطبقات العليا والرصد السطحي والفضائي."},{"type":"text","text":"يحدد السيناريو الأساسي للتطور مع بيان العوامل التي تدعمه من الرصد والنماذج."},{"type":"text","text":"تعرض السيناريوهات البديلة عندما تختلف النماذج أو تكون الحالة حساسة لتغير صغير في المسار أو التوقيت."},{"type":"text","text":"يجب الفصل بين مستوى الثقة في توقيت الحدث وموقعه وشدته ومدته."},{"type":"text","text":"تستخدم الخرائط والرسوم والجداول لتوضيح المعلومة دون ازدحام أو تناقض في الوحدات."},{"type":"text","text":"تتضمن الإحاطة نقاط القرار والفترات التي تستدعي مراقبة إضافية أو تحديثاً للمنتج."},{"type":"text","text":"يجب ذكر وقت إصدار البيانات ومهلة التوقع والمصادر الرئيسة."},{"type":"text","text":"تختتم الإحاطة بخلاصة عملية للقطاعات المعنية مع بيان حدود التوقع."},{"type":"text","text":"مثال: عند توقع حالة مطرية، تعرض الإحاطة توقيت البداية والذروة والتوزيع والاحتمالات وأبرز مناطق عدم اليقين."},{"type":"callout","text":"خلاصة: الإحاطة الفعالة دقيقة ومختصرة وتربط الأدلة العلمية بالاحتياج التشغيلي."}]}',1790,50,'["تنظيم إحاطة جوية","تلخيص الأنظمة المؤثرة","عرض عدم اليقين"]','التحليل التشغيلي وإنتاج التوقع'),
('warning-criteria-and-threshold-management','معايير إصدار التحذيرات وإدارة العتبات','تحديد عتبات الظواهر ومراجعتها وربطها بالاحتمال والأثر المحلي.','{"blocks":[{"type":"text","text":"تحدد عتبات التحذير وفق طبيعة الظاهرة والبيئة المحلية والآثار المتوقعة وقدرة الجهات على الاستجابة."},{"type":"text","text":"قد تشمل العتبات كمية المطر أو سرعة الرياح أو درجة الحرارة أو الرؤية أو ارتفاع الأمواج أو مؤشرات أخرى."},{"type":"text","text":"لا تكفي عتبة رقمية منفردة لتحديد مستوى الخطر دون مراعاة مدة الحدث والتعرض والهشاشة."},{"type":"text","text":"تختلف العتبات بين المناطق بسبب التضاريس والبنية التحتية والتصريف والمناخ المحلي."},{"type":"text","text":"يجب أن تكون العتبات موثقة ومفهومة ومتسقة مع التعاريف التشغيلية المعتمدة."},{"type":"text","text":"تستخدم سجلات الأحداث السابقة لتقييم عدد الإنذارات الصحيحة والخاطئة والأحداث التي لم يصدر بشأنها إنذار."},{"type":"text","text":"قد تؤدي العتبة المنخفضة جداً إلى إنذارات كثيرة، بينما قد تفوت العتبة المرتفعة بعض الأحداث المؤثرة."},{"type":"text","text":"تساعد الاحتمالات التجميعية في دعم القرار عندما لا يكون تجاوز العتبة مؤكداً."},{"type":"text","text":"ينبغي مراجعة العتبات عند تغير المناخ أو العمران أو خصائص الرصد أو أنظمة الاستجابة."},{"type":"text","text":"يجب توثيق من يملك صلاحية اعتماد العتبات وتحديثها ومراجعة نتائجها."},{"type":"text","text":"مثال: عتبة مطر واحدة قد لا تناسب حوضاً حضرياً سريع الاستجابة وحوضاً واسعاً ذا تخزين مرتفع."},{"type":"callout","text":"خلاصة: العتبات أدوات قرار محلية تحتاج بيانات تاريخية ومراجعة دورية وارتباطاً بالأثر."}]}',1800,50,'["فهم عتبات التحذير","تمييز الاحتمال عن الشدة","مراجعة الأداء التاريخي"]','التحذير والتواصل التشغيلي'),
('weather-warning-verification-and-audit','التحقق من التحذيرات والتدقيق بعد الحدث','قياس الإنذارات الصحيحة والخاطئة وفترات المهلة ودقة الأثر المتوقع.','{"blocks":[{"type":"text","text":"يقيس التحقق من التحذيرات مدى توافق الرسالة الصادرة مع الحدث المرصود ومكانه وشدته وتوقيته."},{"type":"text","text":"يعد الإنذار صحيحاً عندما يتحقق الحدث وفق التعريف والعتبة والفترة المحددة مسبقاً."},{"type":"text","text":"الإنذار الكاذب هو تحذير لم يتحقق الحدث المحدد ضمن نطاقه وفترته وفق قواعد التقييم."},{"type":"text","text":"الإنذار الفائت حدث تحقق ولم يصدر بشأنه التحذير المطلوب وفق معيار التقييم."},{"type":"text","text":"تستخدم مصفوفة الالتباس ومقاييس POD وFAR وCSI لتقييم أحداث نعم أو لا."},{"type":"text","text":"يجب تقييم دقة التوقيت والموقع والشدة والمهلة الزمنية كل على حدة."},{"type":"text","text":"تتطلب المقارنة سجلاً موثوقاً للحدث المرصود ولوقت إصدار التحذير وتحديثاته."},{"type":"text","text":"قد تؤدي تقارير الأثر غير المكتملة إلى تقليل دقة التقييم، لذلك ينبغي التنسيق مع الجهات الميدانية."},{"type":"text","text":"تراجع التحذيرات بعد الحدث لتحديد هل كان الخلل في الرصد أو التنبؤ أو العتبة أو صياغة الرسالة أو التوزيع."},{"type":"text","text":"يجب أن تهدف المراجعة إلى التعلم والتحسين لا إلى إخفاء الأخطاء أو تغيير السجلات بعد وقوع الحدث."},{"type":"text","text":"مثال: قد يكون التحذير صحيحاً للظاهرة لكنه ضعيفاً في تحديد نطاقها الزمني، لذلك تفصل مقاييس الأداء."},{"type":"callout","text":"خلاصة: التحقق المنهجي يحول كل حالة إلى فرصة لتحسين التنبؤ والإنذار والتواصل."}]}',1810,50,'["تقييم أداء التحذيرات","شرح الإنذار الفائت والإنذار الكاذب","إجراء مراجعة بعد الحدث"]','التحذير والتواصل التشغيلي'),
('aviation-and-marine-forecast-products','إعداد منتجات التوقعات للطيران والبحر','متطلبات المنتجات التشغيلية للمطارات والملاحة البحرية.','{"blocks":[{"type":"text","text":"تختلف منتجات الطيران والبحر عن التوقع العام لأنها ترتبط بقرارات تشغيلية ومقاييس مكانية وزمنية محددة."},{"type":"text","text":"تتضمن منتجات الطيران تقارير الرصد والتوقع للمطارات ومعلومات الرياح والرؤية والسحب والظواهر الخطرة."},{"type":"text","text":"يجب أن تلتزم تقارير METAR وTAF بالتعاريف والرموز وفترات الصلاحية المعتمدة."},{"type":"text","text":"تحتاج منتجات الطيران إلى متابعة قص الرياح والاضطراب والجليد والعواصف والرؤية وفق مستويات الطيران والمطار."},{"type":"text","text":"تتضمن منتجات البحر الرياح والأمواج والرؤية والهطول والعواصف ومستوى البحر عند الحاجة."},{"type":"text","text":"يجب تحديد المنطقة البحرية أو الساحلية والفترة والوحدات واتجاه الموج وارتفاعه وفق تعريف المنتج."},{"type":"text","text":"تؤثر حركة النظام الجوي وخصائص السواحل والخلجان في التوقع البحري المحلي."},{"type":"text","text":"ينبغي التمييز بين ارتفاع الموج الفردي والارتفاع المعتبر والفترة الموجية عند عرض بيانات البحر."},{"type":"text","text":"تحتاج المنتجات إلى تحديث عند تغير الحالة أو صدور معلومات جديدة ذات أثر تشغيلي."},{"type":"text","text":"يجب أن تكون لغة المنتج واضحة ومحددة وتفصل التوقع عن التحذير."},{"type":"text","text":"مثال: توقع رياح بحرية يجب أن يوضح الفترة والاتجاه والسرعة والهبات المتوقعة والمنطقة البحرية المقصودة."},{"type":"callout","text":"خلاصة: المنتجات القطاعية تتطلب مواصفات موحدة وفهماً لقرار المستخدم ومخاطر النشاط."}]}',1820,50,'["تمييز منتجات الطيران والبحر","فهم متطلبات التوقيت والموقع","صياغة معلومات قطاعية"]','المنتجات القطاعية والتقارير'),
('agrometeorological-bulletin-production','إعداد النشرة الزراعية الجوية','دمج توقعات الطقس مع مراحل المحاصيل والري والصقيع والإجهاد الحراري.','{"blocks":[{"type":"text","text":"تقدم النشرة الزراعية الجوية معلومات الطقس والمناخ التي تساعد المزارعين والجهات الزراعية في التخطيط."},{"type":"text","text":"تبدأ النشرة بتحديد المنطقة والمحاصيل والفترة والمراحل الزراعية ذات الصلة."},{"type":"text","text":"تعرض الحرارة الدنيا والعليا والهطول والرياح والرطوبة والإشعاع عند توافر البيانات."},{"type":"text","text":"تربط توقعات الصقيع بحساسية المحاصيل والارتفاع والتضاريس والظروف الدقيقة للحقل."},{"type":"text","text":"تربط موجات الحر بمرحلة نمو النبات وتوفر الماء وخصائص المحصول."},{"type":"text","text":"تستخدم ET0 وتوقعات المطر لتقدير الظروف العامة للطلب المائي، مع تجنب تقديم تقدير ري دقيق دون بيانات المحصول والتربة."},{"type":"text","text":"توضح النشرة احتمال الهطول وتوزيعه وتراكمه المتوقع بدلاً من تقديم رقم قطعي عند ارتفاع عدم اليقين."},{"type":"text","text":"ينبغي الفصل بين المعلومات الجوية والتوصيات الزراعية المتخصصة التي تتطلب خبرة زراعية محلية."},{"type":"text","text":"تستخدم خرائط الأقاليم الزراعية والمحطات وصور الأقمار لدعم التوزيع المكاني."},{"type":"text","text":"يجب ذكر فترة صلاحية النشرة ومصدر البيانات ووقت إصدارها."},{"type":"text","text":"مثال: نشرة قبل موجة حر توضح توقيت الذروة ومدة استمرارها والاختلاف بين المناطق الزراعية."},{"type":"callout","text":"خلاصة: النشرة الزراعية تربط التوقع الجوي بمرحلة المحصول والاحتياجات التشغيلية."}]}',1830,50,'["تنظيم النشرة الزراعية","ربط الطقس بالقرار الزراعي","صياغة توصيات مبنية على البيانات"]','المنتجات القطاعية والتقارير'),
('climate-monitoring-monthly-bulletin','إعداد النشرة المناخية الشهرية ومراقبة الشذوذات','تلخيص الحرارة والهطول والرياح والتطرفات مقارنة بالمعدلات المرجعية.','{"blocks":[{"type":"text","text":"تلخص النشرة المناخية الشهرية حالة المناخ المرصود خلال شهر مقارنة بخط أساس مرجعي واضح."},{"type":"text","text":"تبدأ بإجراء فحوص اكتمال وجودة السجلات قبل حساب المتوسطات والمجاميع."},{"type":"text","text":"تحسب متوسطات الحرارة الدنيا والعليا ومعدل الهطول ومؤشرات أخرى بحسب شبكة الرصد."},{"type":"text","text":"تقارن النتائج بالمعدلات المناخية المرجعية مع توضيح فترة المرجع ومقدار الشذوذ."},{"type":"text","text":"تستخدم الخرائط لعرض التوزيع المكاني للشذوذات، مع ذكر طريقة الاستيفاء وحدودها."},{"type":"text","text":"تسجل القيم القصوى والدنيا والأحداث اللافتة مع التحقق من صحة السجل وموقع المحطة."},{"type":"text","text":"توضح النشرة التباين بين المناطق ولا تكتفي بمتوسط وطني قد يخفي الفروق الإقليمية."},{"type":"text","text":"يجب التمييز بين غياب البيانات وانعدام الهطول، وبين القيمة المقاسة والقيمة المقدرة."},{"type":"text","text":"تستخدم المؤشرات المناخية لتلخيص الجفاف والحرارة والهطول المتطرف وفق تعريفات معتمدة."},{"type":"text","text":"تتضمن النشرة منهجية الحساب والمصادر وتاريخ الإصدار وأي قيود على التغطية."},{"type":"text","text":"مثال: شهر ذو متوسط وطني قريب من الطبيعي قد يتضمن شذوذاً مطرياً موجباً في الشمال وسالباً في الجنوب."},{"type":"callout","text":"خلاصة: النشرة المناخية الموثوقة تجمع إحصاءً صحيحاً وتفسيراً مكانياً وشفافية منهجية."}]}',1840,50,'["بناء تقرير مناخي شهري","حساب الشذوذات","عرض التطرفات والجودة"]','المنتجات القطاعية والتقارير'),
('post-event-review-and-forecaster-ethics','المراجعة المهنية بعد الحالات الجوية وأخلاقيات المتنبئ','تحليل القرارات والتوثيق والشفافية والمسؤولية العلمية في خدمة الأرصاد.','{"blocks":[{"type":"text","text":"تراجع الحالة الجوية بعد انتهائها لمقارنة التوقعات بالمشاهدات والآثار وتحسين الأداء."},{"type":"text","text":"يبدأ التقييم بتثبيت وقت إصدار كل توقع ونسخته والبيانات المتاحة حينها، لتجنب استخدام معلومات لم تكن متاحة وقت القرار."},{"type":"text","text":"تفصل المراجعة بين خطأ التوقيت والموقع والشدة والنوع والتواصل والأثر المتوقع."},{"type":"text","text":"تراجع مصادر الرصد والنماذج وجودة البيانات وأسباب اختلاف السيناريوهات."},{"type":"text","text":"ينبغي توثيق التعديلات البشرية على مخرجات النماذج مع أسبابها وأدلتها."},{"type":"text","text":"تساعد جلسات المراجعة متعددة التخصصات على كشف فجوات التنسيق بين الأرصاد والهيدرولوجيا والجهات المستفيدة."},{"type":"text","text":"تقتضي النزاهة المهنية الإفصاح عن عدم اليقين وعدم تقديم التوقع الاحتمالي كحقيقة مؤكدة."},{"type":"text","text":"يجب عدم حذف البيانات الأصلية أو تغيير سجل التحذيرات لإخفاء خطأ بعد وقوع الحدث."},{"type":"text","text":"تراعى خصوصية البيانات الشخصية أو التشغيلية عند مشاركة سجلات المحطات والبلاغات والصور."},{"type":"text","text":"تتحول نتائج المراجعة إلى إجراءات تحسين قابلة للقياس وتدريب وتحديث للعتبات والمنتجات."},{"type":"text","text":"مثال: عند خطأ توقيت الهطول، تحدد المراجعة هل السبب في النموذج أم تحديث الرصد أم التفسير أم آلية إصدار المنتج."},{"type":"callout","text":"خلاصة: التطوير المهني يقوم على الشفافية والتوثيق والتعلم المستمر والمسؤولية العلمية."}]}',1850,50,'["إجراء مراجعة بعد الحالة","توثيق القرارات ومصادرها","تطبيق مبادئ النزاهة المهنية"]','الجودة والتطوير المهني'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'إدارة خدمات الأرصاد' then u1.id when 'التحليل التشغيلي وإنتاج التوقع' then u2.id when 'التحذير والتواصل التشغيلي' then u3.id when 'المنتجات القطاعية والتقارير' then u4.id when 'الجودة والتطوير المهني' then u5.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الممارسة المهنية وإدارة خدمات الأرصاد الجوية',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4 cross join u5
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;